package com.habilitesrandom;
import com.habilitesrandom.data.PlayerProfile;import com.habilitesrandom.sanctuary.*;import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;
class RerollAndSanctuaryTest {
 @Test void freeAndFinalRerollStatesAreOneWay(){var p=PlayerProfile.empty(1);var free=p.progress().grantFreeReroll();assertEquals(PlayerProfile.RerollState.FREE_AVAILABLE,free.rerollState());var used=free.consumeFreeReroll();assertEquals(PlayerProfile.RerollState.SANCTUARY_REQUIRED,used.rerollState());var mapped=used.withMap("minecraft:overworld",10,70,20);var profile=p.withProgress(mapped).withIdentity(new PlayerProfile.Identity("habilitesrandom:goku","habilitesrandom:dragon_ball","habilitesrandom:divine","strong","Strong"));assertTrue(SanctuaryService.altarEligible(profile));var granted=SanctuaryService.claimFinalReroll(profile);assertEquals(PlayerProfile.RerollState.SANCTUARY_AVAILABLE,granted.progress().rerollState());assertThrows(IllegalStateException.class,()->SanctuaryService.claimFinalReroll(granted));assertEquals(PlayerProfile.RerollState.EXHAUSTED,granted.progress().consumeSanctuaryReroll().rerollState());}
 @Test void mapEligibilityIsPerProfile(){var base=PlayerProfile.empty(1).withIdentity(new PlayerProfile.Identity("habilitesrandom:goku","habilitesrandom:dragon_ball","habilitesrandom:divine","strong","Strong"));var eligible=base.withProgress(base.progress().grantFreeReroll().consumeFreeReroll());assertTrue(SanctuaryService.mapEligible(eligible));assertFalse(SanctuaryService.mapEligible(base));assertFalse(SanctuaryService.mapEligible(SanctuaryService.purchaseMap(eligible,"minecraft:overworld",1,2,3)));}
 @Test void economyNeverKillsAndNeverChargesHealthWithoutEmeralds(){var missing=SanctuaryEconomy.quote(14,20,15,.5,1);assertFalse(missing.affordable());assertEquals(0,missing.healthCost());var full=SanctuaryEconomy.quote(15,20,15,.5,1);assertTrue(full.affordable());assertEquals(10,full.healthCost());assertEquals(10,full.remainingHealth());var low=SanctuaryEconomy.quote(15,1.5f,15,.5,1);assertTrue(low.affordable());assertTrue(low.remainingHealth()>=1);}
}
